import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.B7PviQjB.js";const l="/docs/images/slides/build-a-deck-final.png",u=JSON.parse('{"title":"Build a deck","description":"Build a three-slide project update deck with a theme, a content slide, a shape, and a transition, then present it.","frontmatter":{"title":"Build a deck","description":"Build a three-slide project update deck with a theme, a content slide, a shape, and a transition, then present it.","type":"tutorial"},"headers":[],"relativePath":"slides/build-a-deck.md","filePath":"slides/build-a-deck.md"}'),s={name:"slides/build-a-deck.md"};function n(d,e,r,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="build-a-deck" tabindex="-1">Build a deck <a class="header-anchor" href="#build-a-deck" aria-label="Permalink to &quot;Build a deck&quot;">​</a></h1><p>Build a three-slide project update deck, then present it full screen. It takes about 10 minutes.</p><p>You will create a title slide, apply a theme, add a bulleted content slide, add a picture and a shape, set a transition, and start the slideshow.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need to be a member of a workspace. See <a href="/docs/collaborate/workspaces.html">Workspaces</a>.</li><li>Use a computer. The phone editor works differently; see <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</li><li>Have a PNG or JPEG image ready, such as a team photo or a product screenshot.</li></ul></div><h2 id="_1-create-the-presentation" tabindex="-1">1. Create the presentation <a class="header-anchor" href="#_1-create-the-presentation" aria-label="Permalink to &quot;1. Create the presentation&quot;">​</a></h2><ol><li>In your workspace, click <strong>New &gt; New presentation</strong>.</li><li>Click <strong>Click to add title</strong> and type <code>Q2 Roadmap</code>.</li><li>Click <strong>Click to add subtitle</strong> and type <code>Project update for the platform team</code>.</li><li>Click an empty part of the slide to finish typing.</li></ol><p>The deck opens on one title slide, and the slide strip on the left shows its thumbnail.</p><h2 id="_2-pick-a-theme" tabindex="-1">2. Pick a theme <a class="header-anchor" href="#_2-pick-a-theme" aria-label="Permalink to &quot;2. Pick a theme&quot;">​</a></h2><ol><li>Click <strong>Theme</strong> at the right end of the toolbar. The <strong>Theme</strong> panel opens on the right.</li><li>On the <strong>Themes</strong> tab, click <strong>Streamline</strong>.</li><li>Click the close button (×) at the top of the panel.</li></ol><p>The whole deck takes the theme&#39;s colors and fonts. Your text stays where it was.</p><h2 id="_3-add-a-content-slide" tabindex="-1">3. Add a content slide <a class="header-anchor" href="#_3-add-a-content-slide" aria-label="Permalink to &quot;3. Add a content slide&quot;">​</a></h2><ol><li><p>In the toolbar, click the arrow next to <strong>Add slide</strong> (tooltip <strong>Choose a layout</strong>).</p></li><li><p>Select <strong>Title and body</strong>. A new slide opens after the title slide.</p></li><li><p>Click <strong>Click to add title</strong> and type <code>Q2 goals</code>.</p></li><li><p>Click <strong>Click to add text</strong> and type three lines, pressing <code>Enter</code> after each:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ship the new onboarding flow</span></span>
<span class="line"><span>Cut page load time by 30%</span></span>
<span class="line"><span>Launch the partner API beta</span></span></code></pre></div></li><li><p>Select the three lines and click <strong>Bulleted list</strong> in the toolbar.</p></li><li><p>Click <strong>Done</strong> at the end of the toolbar.</p></li></ol><h2 id="_4-add-a-picture-and-a-shape" tabindex="-1">4. Add a picture and a shape <a class="header-anchor" href="#_4-add-a-picture-and-a-shape" aria-label="Permalink to &quot;4. Add a picture and a shape&quot;">​</a></h2><ol><li>Click the arrow next to <strong>Add slide</strong> and select <strong>Title only</strong>. Type <code>Team</code> as the title, then click an empty part of the slide.</li><li>Click <strong>Insert image</strong> (the picture icon) and choose your image file. The image appears centered on the slide.</li><li>Drag the image to the left half of the slide, and drag a corner handle to resize it.</li><li>Click <strong>Shape</strong> (the shapes icon) and select <strong>Rounded rectangle</strong>.</li><li>Drag on the right half of the slide to draw the shape, then type <code>On track</code> to put a label in it.</li><li>Click an empty part of the slide, click the shape again, then click <strong>Fill color</strong> and choose an accent color from the theme row.</li></ol><h2 id="_5-add-a-transition" tabindex="-1">5. Add a transition <a class="header-anchor" href="#_5-add-a-transition" aria-label="Permalink to &quot;5. Add a transition&quot;">​</a></h2><ol><li>Click <strong>Motion</strong> at the right end of the toolbar.</li><li>Under <strong>Transition</strong>, set <strong>Type</strong> to <strong>Fade</strong> and <strong>Speed</strong> to <strong>Medium</strong>.</li><li>Click <strong>Apply to all slides</strong>.</li></ol><p>Every slide now fades in when you present.</p><h2 id="_6-present-the-deck" tabindex="-1">6. Present the deck <a class="header-anchor" href="#_6-present-the-deck" aria-label="Permalink to &quot;6. Present the deck&quot;">​</a></h2><ol><li>Click the first slide in the slide strip.</li><li>Click <strong>Slideshow</strong> in the header. The deck fills the screen.</li><li>Press <code>→</code> or click to move forward, and <code>←</code> to go back.</li><li>Press <code>Escape</code> to return to the editor.</li></ol><p><img src="`+l+'" alt="Finished three-slide Q2 Roadmap deck in the Streamline theme, with the Team slide open"></p><p>Your deck should now have three slides in the Streamline theme: a title slide, a bulleted goals slide, and a Team slide with a picture and a labeled shape.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/slides/add-content.html">Add text, images, and shapes</a> to learn the other ways to fill a slide.</li><li><a href="/docs/slides/themes-and-layouts.html">Apply a theme and set backgrounds</a> to customize the theme&#39;s colors and fonts.</li><li><a href="/docs/slides/animations.html">Add transitions and animations</a> to bring objects onto a slide one at a time.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to invite your team to edit the deck.</li></ul>',23)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
